{
  "findings": [
    {
      "check_id": "CKV_GCP_40",
      "title": "Compute instance has a public IP address",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "HIGH",
      "explanation": "The `access_config {}` block assigns an ephemeral public IP to the instance. For an internal orchestration engine, this unnecessarily exposes the VM to the internet, increasing the attack surface."
    },
    {
      "check_id": "CKV_GCP_31",
      "title": "Service account has full access to all Cloud APIs",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "HIGH",
      "explanation": "The service account scope is set to `cloud-platform`, which grants full access to all Google Cloud APIs. This violates the principle of least privilege; if the VM is compromised, the attacker gains broad cloud permissions."
    },
    {
      "check_id": "CKV_GCP_35",
      "title": "Serial port access is enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The metadata key `serial-port-enable` is set to `true`. This allows interactive serial console access, which can be used for debugging but also provides a potential backdoor or information leakage vector if not strictly required."
    },
    {
      "check_id": "CKV_GCP_32",
      "title": "Block project-wide SSH keys is not enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance does not explicitly disable project-wide SSH keys via metadata (`block-project-ssh-keys = true`). If project-wide keys are defined, they could inadvertently grant SSH access to this instance."
    },
    {
      "check_id": "CKV_GCP_39",
      "title": "Shielded VM features are not enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The `shielded_instance_config` block is missing. Shielded VMs provide verifiable integrity and secure boot capabilities, which are critical for security-sensitive infrastructure like disaster recovery orchestration."
    }
  ],
  "patched_code": "resource "google_compute_instance" "backup_orchestration_engine" {
  name         = "enterprise-disaster-recovery-orchestration-platform-compute-orchestration"
  machine_type = "e2-medium"
  zone         = "${var.primary_region}-a"
  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-11"
      size  = 50
    }
  }
  network_interface {
    network    = google_compute_network.dr_vpc.id
    subnetwork = google_compute_subnetwork.management_subnet.id
    # Removed access_config to prevent public IP assignment (CKV_GCP_40)
  }
  service_account {
    email  = "123456789-compute@developer.gserviceaccount.com"
    # Changed from cloud-platform to specific scopes to enforce least privilege (CKV_GCP_31)
    # Note: Adjust scopes based on actual needs. Using empty list or specific read-only scopes is safer.
    # Here we remove the overly permissive scope. If specific API access is needed, add them explicitly.
    scopes = []
  }
  metadata = {
    # Disabled serial port access (CKV_GCP_35)
    serial-port-enable     = false
    # Explicitly block project-wide SSH keys (CKV_GCP_32)
    block-project-ssh-keys = true
    startup-script         = file("${path.module}/scripts/orchestration-startup.sh")
  }
  tags = ["dr-internal", "orchestration-engine"]

  # Enable Shielded VM features (CKV_GCP_39)
  shielded_instance_config {
    enable_secure_boot          = true
    enable_vtpm                 = true
    enable_integrity_monitoring = true
  }

  depends_on = [
    google_storage_bucket.primary_backup_storage,
    google_sql_database_instance.recovery_database
  ]
}",
  "fix_summary": "Removed the public IP configuration by deleting `access_config`. Restricted service account privileges by removing the `cloud-platform` scope. Disabled serial port access and explicitly blocked project-wide SSH keys in metadata. Added `shielded_instance_config` to enable Secure Boot, vTPM, and Integrity Monitoring."
}
